/**
 * @name Open redirect
 * @description Redirecting to a user-controlled URL can lead to phishing attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/open-redirect
 * @tags security
 *        external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module OpenRedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // HTTPFound, HTTPMovedPermanently, HTTPSeeOther, etc.
      call = API::moduleImport("aiohttp").getMember("web").getMember([
        "HTTPFound", "HTTPMovedPermanently", "HTTPSeeOther", 
        "HTTPTemporaryRedirect", "HTTPPermanentRedirect"
      ]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::AttrWrite write |
      write.getAttributeName() = "location" and
      sink = write.getValue()
    )
  }
}

module OpenRedirectFlow = TaintTracking::Global<OpenRedirectConfig>;
import OpenRedirectFlow::PathGraph

from OpenRedirectFlow::PathNode source, OpenRedirectFlow::PathNode sink
where OpenRedirectFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Open redirect from $@.", source.getNode(), "user input"

/**
 * @name HTTP header injection
 * @description Injecting user-controlled data into HTTP headers can lead to header injection attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/http-header-injection
 * @tags security
 *        external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        // aiohttp Response constructor
        call = API::moduleImport("aiohttp").getMember("web").getMember("Response").getACall() or
        // Django HttpResponse with headers parameter
        call = API::moduleImport("django").getMember("http").getMember("HttpResponse").getACall()
      ) and
      sink = call.getArg(_)
    )
    or
    // Flask response.headers assignment
    exists(DataFlow::AttrWrite write |
      write.getAttributeName() = "headers" and
      sink = write.getValue()
    )
    or
    // Header setting methods
    exists(DataFlow::CallCfgNode headerCall |
      (
        headerCall.getFunction().(DataFlow::AttrRead).getAttributeName() = "add_header" or
        headerCall.getFunction().(DataFlow::AttrRead).getAttributeName() = "set_header" or
        headerCall.getFunction().(DataFlow::AttrRead).getAttributeName() = "__setitem__"
      ) and
      sink = headerCall.getArg(_)
    )
  }
}

module HeaderInjectionFlow = TaintTracking::Global<HeaderInjectionConfig>;
import HeaderInjectionFlow::PathGraph

from HeaderInjectionFlow::PathNode source, HeaderInjectionFlow::PathNode sink
where HeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "HTTP header injection from $@.", source.getNode(), "user input"

